#include <algorithm>
#include <atomic>
#include <chrono>
#include <thread>

#include "backend.hpp"

// Generated by slangc -target cpp from shaders/aether_far.slang (see CMakeLists.txt).
struct AetherGroupRange {
    uint32_t start[3];
    uint32_t end[3];
};
extern "C" void farMain(void* varyingInput, void* entryPointParams, void* globalParams);

namespace aether {
namespace {

template <typename T>
CpuBuffer<T> view(const std::vector<T>& v) {
    return {const_cast<T*>(v.data()), v.size()};
}

class CpuBackend final : public Backend {
public:
    const char* name() const override { return "cpu (slang->c++)"; }

    bool render(const FrameInputs& in, FrameTargets& out, double* ms, std::string&) override {
        auto t0 = std::chrono::steady_clock::now();
        uint32_t w = in.frame.dims[0], h = in.frame.dims[1];
        size_t n = size_t(w) * h;
        out.color.assign(n, 0);
        out.normal.assign(n, 0);
        out.depth.assign(n, 0.0f);
        out.counters.assign(n, 0);
        FrameGpu frame = in.frame;
        const PackedScene& s = *in.scene;
        FarGlobals g{};
        g.frame = &frame;
        g.regionTable = view(s.table);
        g.regions = view(s.regions);
        g.nodes = view(s.nodes);
        g.leaves = view(s.leaves);
        g.runEnd = view(s.runEnd);
        g.runMat = view(s.runMat);
        g.palette = view(*in.palette);
        g.outColor = view(out.color);
        g.outNormal = view(out.normal);
        g.outDepth = view(out.depth);
        g.weather = view(*in.weather);
        g.counters = view(out.counters);

        uint32_t gx = (w + 7) / 8, gy = (h + 7) / 8;
        std::atomic<uint32_t> nextRow{0};
        auto worker = [&] {
            for (;;) {
                uint32_t row = nextRow.fetch_add(1);
                if (row >= gy) return;
                AetherGroupRange r{{0, row, 0}, {gx, row + 1, 1}};
                farMain(&r, nullptr, &g);
            }
        };
        unsigned threads = std::max(1u, std::thread::hardware_concurrency());
        std::vector<std::thread> pool;
        for (unsigned i = 0; i + 1 < threads; i++) pool.emplace_back(worker);
        worker();
        for (auto& t : pool) t.join();
        if (ms) *ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
        return true;
    }
};

}  // namespace

std::unique_ptr<Backend> makeCpuBackend() { return std::make_unique<CpuBackend>(); }

}  // namespace aether
